  todo: { icon: '✅', name: 'Откликнусь и 🤔', statuses: ['approved', 'maybe'] },
  sent: { icon: '📨', name: 'Отправлено', statuses: ['applied'] },
  skip: { icon: '❌', name: 'Мимо и устаревшие', statuses: ['skipped', 'expired', 'archived'] },
  rej: { icon: '🚫', name: 'Отсеяно фильтром', statuses: ['rejected'] },
  all: { icon: '📋', name: 'Все', statuses: null },
};

// Значки строки списка: решение нейросети + статус
const VERDICT_ICON = { apply: '🟢', maybe: '🟡', skip: '🔴', error: '⚠️' };
const STATUS_ICON = {
  new: '⚙️',
  detailed: '⚙️',
  scoring: '⚙️',
  waiting: '⏳',
  approved: '✅',
  maybe: '🤔',
  skipped: '❌',
  applied: '📨',
  expired: '⌛',
  archived: '🔒',
  rejected: '🚫',
};
// Значок строки с учётом робота: в очереди 🕒, отправляется 🤖, отправлен роботом 🚀
const statusIcon = (r) =>
  r.apply_state === 'queued'
    ? '🕒'
    : r.apply_state === 'applying'
      ? '🤖'
      : r.status === 'applied' && r.apply_by === 'robot'
        ? '🚀'
        : (STATUS_ICON[r.status] ?? '');

const job = $('Job').first().json;
const s = loadSettings($('Settings').all());
const queue = $('Queue')
  .all()
  .map((i) => i.json)
  .filter((r) => r.id);
const now = Date.now();
const today = robotToday(
  $('Today')
    .all()
    .map((i) => i.json)
    .filter((r) => r.id),
  now,
);
const h = $('Health').first()?.json ?? {};
const health = h.ok && !h.error ? h : null;
const state = $getWorkflowStaticData('global');
const dayKey = new Date(robotDayStart(now)).toISOString().slice(0, 10);
const limit = s['apply.daily_limit'];
const out = { heal: [], next: null, wait: '', notice: null, resolved: null, views: [] };

// 1. Починка
for (const r of queue) {
  // Резюме вакансии расстались с hh уже после 🚀 (удалили, отвязали) — из очереди: откликнулись бы не тем
  if (r.status !== 'approved' || !robotResume(s, r).ok) out.heal.push({ id: r.id, to: '' });
  else if (r.apply_state === 'applying' && now - Date.parse(r.updatedAt) > 6 * 60 * 1000) out.heal.push({ id: r.id, to: 'queued' });
}
const healed = new Map(out.heal.map((x) => [x.id, x.to]));
const queued = queue.filter((r) => r.status === 'approved' && (healed.get(r.id) ?? r.apply_state) === 'queued');
const applying = queue.some((r) => r.status === 'approved' && r.apply_state === 'applying' && !healed.has(r.id));

// 2. Можно ли сейчас
if (!s['apply.enabled']) out.wait = 'disabled';
else if (s['apply.paused']) out.wait = 'paused';
else if (!health) out.wait = 'down';
else if (health.blocked) out.wait = 'blocked';
else if (health.busy || applying) out.wait = 'busy';
else if (today >= limit) out.wait = 'limit';

// 3. Сообщения: блок — один раз на блок (по since), «не отвечает» и «лимит» — раз в «день» робота
const loud = job.fromUser || !quietHours(now);
const BLOCK = {
  captcha: 'капчу hh',
  smart: 'капчу в окне робота',
  login: 'вход в hh',
  limit: 'лимит hh (200 откликов за сутки)',
  errors: 'проверку после сбоев',
  blocked: 'проверку аккаунта',
};
if (out.wait === 'blocked') {
  const b = health.blocked;
  if (state.alertedSince !== b.since) {
    state.alertedSince = b.since;
    const vnc = `«Общий экран» → ${VNC_URL} (режим «Управление»)`;
    const texts = {
      login: `🔑 <b>Робот вышел из hh</b> — очередь ждёт.\nВойдите: ${vnc} или <code>node scripts/applier.mjs login</code>, затем ▶️.`,
      // «Я не робот» или капча внутри окна отклика: ответ на фото отправил бы и сам отклик — решает человек
      smart: `🧩 <b>hh просит капчу</b> — очередь ждёт.\nРешите её в окне робота: ${vnc}, затем ▶️.`,
      errors: `⚠️ <b>Робот трижды подряд не смог откликнуться</b> — пауза. Посмотрите скриншоты; продолжить — ▶️.`,
      limit: `⏸ <b>hh: лимит 200 откликов за сутки</b> — робот ждёт${b.until ? ` до ${localDate(b.until)} ${localTime(b.until)}` : ''}, дальше сам.`,
      blocked: `⛔ <b>hh не принял отклик</b>${b.note ? `: «${esc(b.note)}»` : ''} — робот на паузе. Проверьте аккаунт; продолжить — ▶️.`,
    };
    out.notice =
      b.kind === 'captcha' && b.shot
        ? {
            kind: 'captcha',
            key: `block:${b.since}`,
            shot: b.shot,
            text: `${ROBOT_PROMPTS.captcha} — ответьте на это фото текстом с картинки.\nНе читается — решите в окне робота (${VNC_URL}) и пришлите /go${
              health.fake ? '\n🧪 Фейковый робот: ответьте «ok»' : ''
            }`,
            silent: !loud,
          }
        : {
            kind: 'alert',
            key: `block:${b.since}`,
            shot: b.shot ?? '',
            text: texts[b.kind] ?? `⏸ Робот ждёт: ${BLOCK[b.kind] ?? esc(b.kind)}. Продолжить — ▶️.`,
            silent: !loud,
            button: b.kind !== 'limit',
          };
  }
} else if (state.alertedSince && health) {
  // Блок сняли (▶️, /go, истёк сам) — прошлую тревогу поправить
  out.resolved = {
    messageId: state.alertMessageId ?? 0,
    text: `✅ Робот снова в работе · ${localTime(new Date(now).toISOString())}`,
    // Фото капчи больше не нужно (решили через /go или «Общий экран») — удалить, чтобы на него не отвечали
    promptId: state.captchaPromptId ?? 0,
  };
  state.alertedSince = null;
  state.alertMessageId = null;
  state.captchaPromptId = null;
}
if (!out.notice && out.wait === 'down' && queued.length && state.downDay !== dayKey) {
  state.downDay = dayKey;
  out.notice = {
    kind: 'info',
    key: `down:${dayKey}`,
    text: `⚠️ Робот-отклик не отвечает — очередь (${queued.length}) ждёт.\nЗапуск: <code>scripts/deploy.sh --applier</code>`,
    silent: !loud,
  };
}
if (!out.notice && out.wait === 'limit' && queued.length && state.limitDay !== dayKey) {
  state.limitDay = dayKey;
  out.notice = {
    kind: 'info',
    key: `limit:${dayKey}`,
    text: `⏸ Лимит робота на сегодня — ${limit} откликов. Очередь (${queued.length}) уйдёт после 09:00; поменять — ⚙️ → 🚀 Робот`,
    silent: true,
  };
}

// 4. Нажали 🚀, а робот ждёт — письмо сразу говорит, чего
const WAIT = { paused: 'снятия паузы (⚙️ → 🚀 Робот)', down: 'запуска робота', blocked: BLOCK[health?.blocked?.kind] ?? 'проверки', limit: 'завтра, после 09:00 (лимит дня)' };
if (job.fromUser && job.op === 'enqueue' && WAIT[out.wait]) {
  const r = queued.find((x) => x.id === job.id);
  if (r) {
    out.views.push({
      id: r.id,
      chatId: job.chatId,
      messageId: r.tg_letter_id,
      layout: 'wait',
      url: r.url,
      apply_url: r.apply_url,
      text: letterText({ ...r, ok: Boolean(r.letter), mode: 'new', robot_wait: WAIT[out.wait] }),
    });
  }
}

// 5. Кого отправлять
if (!out.wait && queued.length) out.next = { ...queued[0], resume: robotResume(s, queued[0]).resume };
return [{ json: out }];

// W9 · Heal items — починка очереди из «Gate» (heal) → по item на запись «Heal».
// Нода: Code, режим «Run Once for All Items». Выход: [{ id, to }] — to: queued (зависла на отправке) | '' (снять)
return ($('Gate').first().json.heal ?? []).map((h) => ({ json: h }));

// W9 · Notice item — сообщение к отправке (от «Gate» или «Captcha plan») — один item, на него ссылаются ноды ниже.
// Нода: Code, режим «Run Once for All Items». Выход: { notice }
return [{ json: { notice: $input.first().json.notice } }];

// W9 · Remember — запомнить отправленную тревогу или фото капчи (static data global):
//   alertMessageId — тревога о блоке: когда блок снимут, «Gate» поправит её на «✅ снова в работе»;
//   captchaPromptId — фото капчи (ответ на него — текст капчи; W3 узнаёт ответ по подписи).
// Нода: Code, режим «Run Once for All Items». Вход: ответ Telegram { result: { message_id } } или { error }.
const state = $getWorkflowStaticData('global');
const sent = $input.first()?.json?.result?.message_id;
const kind = $('Notice item').first()?.json?.notice?.kind;
if (sent && kind === 'captcha') state.captchaPromptId = sent;
else if (sent) state.alertMessageId = sent;
return [{ json: { messageId: sent ?? 0 } }];

// W9 · Gate views — письма, которые «Gate» просит перерисовать (нажали 🚀, а робот ждёт) → по item на «View».
// Нода: Code, режим «Run Once for All Items».
return ($('Gate').first().json.views ?? []).map((v) => ({ json: v }));

// W9 · Result — исход отклика робота → строка вакансии, письмо, карточка, скриншот, продолжать ли очередь.
// Нода: Code, режим «Run Once for All Items». Вход: «Apply» — ответ робота POST /apply (полный: statusCode, body;
// нет связи — { error }); «Gate» → next — вакансия, которую взяли («Claim»); «Job».
// Выход: { id, chatId, messageId, layout, text, url, apply_url — вид письма для «View»;
//          row — что записать («Save result»); card — { messageId, text } или null; shot — скриншот при сбое;
//          sync — задание W7 (перерисовать панель); more — сразу вызвать W9 снова (очередь не пуста) }
// Группы исходов (applier/src/hh/state.mjs → GROUP): done | manual | closed | block | error | dry; ответы HTTP:
//   409 (робот занят), 5xx, нет связи → retry — назад в очередь без счёта попыток; 423 (блок), 429 (потолок дня
//   робота) → block. Таймаут — тоже retry: если робот успел откликнуться, при повторе он увидит «уже откликались».

// Время человека (13.10.2026, docs/onboarding.md): часовой пояс — настройка profile.tz (IANA, например Asia/Bangkok),
// иначе пояс компьютера (USER_TZ из .env — его пишет мастер установки), иначе Москва. Расписание сбора по-прежнему
// считается по Москве (n8n/shared/schedule.js): hh публикует вакансии по МСК.
// Общий код: строка «// @include n8n/shared/time.js» — раньше n8n/shared/card.js и n8n/shared/robot.js (им нужен TZ).
// Пояс берётся из ноды «Settings», если она есть в workflow и уже выполнилась; без неё — USER_TZ.

const MSK_TZ = 'Europe/Moscow';
const validTz = (tz) => {
  try {
    return Boolean(tz) && Boolean(new Intl.DateTimeFormat('en-GB', { timeZone: tz }));
  } catch {
    return false;
  }
};

// Пояс этого запуска
function currentTz() {
  let tz = '';
  try {
    const row = $('Settings')
      .all()
      .map((i) => i.json)
      .find((r) => r?.name === 'profile.tz');
    tz = row ? JSON.parse(row.value_json) : '';
  } catch {
    // в workflow нет ноды «Settings» или строка битая — пояс компьютера
  }
  const env = typeof $env === 'undefined' ? '' : $env.USER_TZ;
  return [tz, env, MSK_TZ].find(validTz);
}
const TZ = currentTz();

// Части даты в поясе tz числами: { y, mo, d, h, mi }
function zonedParts(ms, tz = TZ) {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  }).formatToParts(new Date(ms));
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  return { y: get('year'), mo: get('month'), d: get('day'), h: get('hour'), mi: get('minute') };
}
const pad2 = (n) => String(n).padStart(2, '0');

// 1760340720000 → '14:32'
const localHM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.h)}:${pad2(p.mi)}`;
};
// → '07.10'
const localDM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.d)}.${pad2(p.mo)}`;
};
// → '2026-10-07' — ключ дня
const localDay = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${p.y}-${pad2(p.mo)}-${pad2(p.d)}`;
};
const localHour = (ms, tz = TZ) => zonedParts(ms, tz).h;

// Смещение пояса от UTC в минутах в момент ms (Бангкок: +420)
function tzOffsetMin(ms, tz = TZ) {
  const p = zonedParts(ms, tz);
  return Math.round((Date.UTC(p.y, p.mo - 1, p.d, p.h, p.mi) - Math.floor(ms / 60000) * 60000) / 60000);
}

// 'UTC+7', 'UTC+5:30', 'UTC−4'
function tzLabel(tz = TZ, ms = Date.now()) {
  const off = tzOffsetMin(ms, tz);
  const abs = Math.abs(off);
  return `UTC${off < 0 ? '−' : '+'}${Math.floor(abs / 60)}${abs % 60 ? `:${pad2(abs % 60)}` : ''}`;
}

// Начало «дня», который начинается в hour:00 по местному: последний такой момент не позже ms
function localDayStart(ms, tz = TZ, hour = 0) {
  const p = zonedParts(ms, tz);
  let start = Date.UTC(p.y, p.mo - 1, p.d, hour) - tzOffsetMin(ms, tz) * 60000;
  if (start > ms) start -= 24 * 3600 * 1000;
  return start;
}

// Тихие часы 23:00–09:00 по местному: карточки и сводка — без звука, тревоги — со звуком
const quietHours = (ms = Date.now(), tz = TZ) => {
  const h = localHour(ms, tz);
  return h >= 23 || h < 9;
};

// Время по местному и в скобках по Москве: '14:32 (10:32 МСК)'; пояс совпадает с Москвой — '10:32 МСК'
const localMsk = (ms, tz = TZ) =>
  tzOffsetMin(ms, tz) === tzOffsetMin(ms, MSK_TZ) ? `${localHM(ms, MSK_TZ)} МСК` : `${localHM(ms, tz)} (${localHM(ms, MSK_TZ)} МСК)`;

// Момент ISO (applied_at) → дата и время по местному: '2026-10-06T21:17:55Z' → '07.10', '04:17'
const localDate = (iso) => (Date.parse(iso) ? localDM(Date.parse(iso)) : '');
const localTime = (iso) => (Date.parse(iso) ? localHM(Date.parse(iso)) : '');

// Общий код карточки вакансии в Telegram: W2 «Format card» и W3 «Apply choice».
// В Code-ноду попадает при сборке: строка «// @include n8n/shared/card.js» заменяется этим файлом
// (scripts/build-workflows.mjs, scripts/run-code-node.mjs). Раньше него — n8n/shared/time.js (localDate).

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const EXPERIENCE = { noExperience: 'без опыта', between1And3: '1–3 г.', between3And6: '3–6 л.', moreThan6: '6+ л.' };
const CURRENCY = { RUR: '₽', USD: '$', EUR: '€', KZT: '₸', BYR: 'Br', UZS: 'сум' };

// Решение нейросети (колонка decision)
const VERDICT = { apply: '🟢 apply', maybe: '🟡 maybe', skip: '🔴 skip', error: '⚠️ не оценено' };
// Кнопки пользователя: callback_data = v:<id строки>:<choice>, решение — в колонку my_decision.
// earlier — «📨 Уже откликался» (до бота, 07.10.2026): status = applied без письма и без applied_at,
// без «Почему?» и вне теневого режима (сравниваются только apply / maybe / skip)
const CHOICE = { apply: '✅ Откликнусь', maybe: '🤔 Возможно', skip: '❌ Мимо', earlier: '📨 Откликался раньше' };
// «🚫 В ЧС» на карточке (07.10.2026): компания уходит в чёрный список, вакансия — ❌ с этой причиной
const BAN_REASON = 'чёрный список';
const STATUS_BY_CHOICE = { apply: 'approved', maybe: 'maybe', skip: 'skipped', earlier: 'applied' };

const short = (n) => (n >= 1000 ? `${Math.round(n / 1000)}k` : String(n));

function salary(r) {
  if (!r.salary_from && !r.salary_to) return '';
  const range =
    r.salary_from && r.salary_to
      ? `${short(r.salary_from)}–${short(r.salary_to)}`
      : r.salary_from
        ? `от ${short(r.salary_from)}`
        : `до ${short(r.salary_to)}`;
  return `💰 ${range} ${CURRENCY[r.currency] ?? r.currency ?? ''}${r.salary_gross ? ' до налогов' : ''}`;
}

// «Москва, Сербия, Грузия, Армения» → «Москва, Сербия +2»
function areas(s) {
  const list = String(s ?? '').split(', ').filter(Boolean);
  return list.length > 2 ? `${list.slice(0, 2).join(', ')} +${list.length - 2}` : list.join(', ');
}

// '2026-10-06T13:22:00+0300' → '06.10'
function published(s) {
  const m = String(s ?? '').match(/^\d{4}-(\d{2})-(\d{2})/);
  return m ? `${m[2]}.${m[1]}` : '';
}

// Итоговые состояния без кнопок: W3 «📨 Отправил», W6 «⌛ устарела» и «🔒 закрыта на hh»
const FINAL = { expired: '⌛ Устарела: 3 дня без решения', archived: '🔒 Вакансия закрыта на hh' };

// Текст карточки (Parse Mode = HTML). Строка «👤 …» появляется после нажатия кнопки,
// «📨 …» — после «Отправил» под письмом (W3, status = applied), FINAL — после W6
function cardText(r) {
  const date = published(r.published_at);
  const meta = [esc(r.company), salary(r), EXPERIENCE[r.experience] ?? '', esc(areas(r.areas)), date && `📅 ${date}`]
    .filter(Boolean)
    .join(' · ');
  const flags = [
    r.has_test && '📝 тест',
    r.letter_required && '✉️ письмо обязательно',
    r.responses != null && `👥 ${r.responses}`,
    r.error && `⚠️ ${esc(r.error)}`,
  ]
    .filter(Boolean)
    .join(' · ');
  // Нейросеть не оценивала, а фильтр отсеял (в том числе вакансия, возвращённая с панели меню, 08.10.2026) — причины фильтра
  const verdict =
    !r.decision && r.reasons
      ? `🧹 Отсеяна фильтром: ${esc(r.reasons)}`
      : `🤖 ${VERDICT[r.decision] ?? esc(r.decision)}${r.llm_reason ? ` — ${esc(r.llm_reason)}` : ''}`;
  const mine = CHOICE[r.my_decision]
    ? `👤 ${CHOICE[r.my_decision]}${r.my_reason === BAN_REASON ? ' · 🚫 компания в чёрном списке' : ''}`
    : '';
  // «📨 Откликался раньше» уже в строке «👤 …» — второй раз не пишем
  // Робот (этап 6): «🚀 … роботом»; нашёлся на hh без «📨 Отправил» (6.2) — «📨 … на hh»
  const who = r.apply_by === 'robot' ? '🚀 Отклик отправлен роботом' : r.apply_by === 'hh' ? '📨 Отклик есть на hh' : '📨 Отклик отправлен';
  const sent =
    r.status === 'applied' && r.my_decision !== 'earlier' ? `${who}${r.applied_at ? ` ${localDate(r.applied_at)}` : ''}` : '';
  // Несколько резюме (docs/resumes.md): вакансия не основного резюме — его название (пишет W1)
  const resume = r.resume_id && r.resume_name ? `📄 ${esc(r.resume_name)}` : '';
  return [`<a href="${r.url}"><b>${esc(r.title)}</b></a>`, meta, resume, flags, verdict, mine, sent, FINAL[r.status] ?? '']
    .filter(Boolean)
    .join('\n');
}
// Общий код робота-отклика (этап 6, docs/stages/stage-6.md): W3, W5, W6, W7, W9.
// Подключается строкой «// @include n8n/shared/robot.js» после n8n/shared/time.js и n8n/shared/card.js (нужны TZ,
// localDate, localTime и esc).

const VNC_URL = 'vnc://localhost:5901';

// Можно ли откликнуться роботом: ✅ с письмом, без теста работодателя и не на сайте работодателя, не в очереди.
// enabled — настройка apply.enabled (W3 её не читает: выключенного робота поймает W9 при нажатии)
const robotEligible = (r, enabled = true) =>
  Boolean(enabled && r?.status === 'approved' && r.letter && !r.has_test && r.apply_type !== 'external' && !r.apply_state);

// Каким резюме hh откликаться (несколько резюме, docs/resumes.md): резюме вакансии — resume_id (пусто — основное).
// Нужен n8n/shared/resumes.js. → { ok: true, resume: { hash, title } } — резюме связано с резюме на hh, робот выберет его
// в окне отклика; { ok: true, resume: null } — основное не связано: робот откликнется резюме по умолчанию (как раньше);
// { ok: false, reason } — другое резюме не связано с hh: роботом откликаться нельзя, откликнулось бы не тем резюме
function robotResume(s, row) {
  const id = row?.resume_id && resumeById(s, row.resume_id) ? row.resume_id : 'r1';
  const r = resumeById(s, id);
  if (r?.hh?.hash) return { ok: true, resume: { hash: r.hh.hash, title: r.hh.title } };
  if (id === 'r1') return { ok: true, resume: null };
  return {
    ok: false,
    reason: `резюме «${r?.name ?? id}» не связано с резюме на hh: импортируйте его (⚙️ → 📄 Резюме → 📥 Импорт с hh) или откликнитесь вручную`,
  };
}

// «День» робота для лимита — с 09:00 по местному (решение пользователя 10.10.2026): отложенные на завтра отклики
// уходят, когда тихие часы (23–09) закончились
const robotDayStart = (now = Date.now(), tz = TZ) => localDayStart(now, tz, 9);
// Живые отклики робота за текущий «день»
const robotToday = (rows, now = Date.now()) =>
  rows.filter((r) => r.apply_by === 'robot' && Date.parse(r.applied_at) >= robotDayStart(now)).length;

// Как ушло письмо — в строку «🚀 Отправлено»
const LETTER_HOW = { attached: ' · ✉️ письмо приложено', chat: ' · 💬 письмо — в чате отклика', none: ' · ⚠️ без письма' };

// Строка робота в сообщении с письмом: очередь, итог, пометка. r — строка вакансии
// (+ robot_wait — чего ждёт робот: «капчу hh», «вход в hh»…)
function robotLine(r) {
  if (r.apply_state === 'queued' || r.apply_state === 'applying') {
    return r.robot_wait ? `⏸ Робот ждёт: ${esc(r.robot_wait)}` : '⏳ Робот откликается…';
  }
  if (r.status === 'applied' && r.apply_by === 'robot') {
    return `🚀 Отправлено ${localDate(r.applied_at)} ${localTime(r.applied_at)}${LETTER_HOW[r.apply_letter] ?? ''}${
      r.apply_note ? `\n⚠️ hh: ${esc(r.apply_note)}` : ''
    }`;
  }
  if (r.status === 'applied' && r.apply_by === 'hh') return '📨 Отклик уже был на hh — отметил';
  if (r.status !== 'approved') return '';
  const note = r.apply_note ? `: ${esc(r.apply_note)}` : '';
  const lines = {
    test: '🧩 У вакансии вопросы работодателя — откликнитесь сами',
    external: '🌐 Отклик на сайте работодателя — откликнитесь сами',
    // Скрыто конкретное резюме (несколько резюме, этап 5): робот называет его в заметке
    hidden: `🙈 ${/^резюме/.test(r.apply_note ?? '') ? esc(r.apply_note) : 'hh просит открыть резюме этому работодателю'} — откликнитесь сами`,
    error: `⚠️ Робот не смог${note}${(r.apply_tries ?? 0) >= 3 ? ' — третий раз, откликнитесь сами' : ''}`,
    dry_run: `🧪 Сухой прогон (APPLY_LIVE=0), отклик не отправлен${note}`,
    disabled: '⏸ Робот выключен (⚙️ → 🚀 Робот) — откликнитесь сами',
    no_resume: `📄 Робот не откликается: ${esc(r.apply_note || 'резюме не связано с резюме на hh')}`,
  };
  return lines[r.apply_result] ?? '';
}
// Общий код сообщения с письмом в Telegram: W5 «Format letter», W3 «Apply sent», W9 Robot.
// Подключается после n8n/shared/card.js (нужны esc и thaiDate) и n8n/shared/robot.js (строка робота):
//   // @include n8n/shared/card.js
//   // @include n8n/shared/robot.js
//   // @include n8n/shared/letter.js

const LETTER_HEAD = { new: '✉️ Письмо', redo: '🔄 Новый вариант письма', revise: '✏️ Письмо с правкой' };
// Нейросеть повторилась (W5 «Parse letter», same; 14.10.2026): письмо всё равно отправлено — на него можно ответить правкой
const LETTER_SAME = {
  revise: '⚠️ Нейросеть не поменяла письмо. Напиши пожелание иначе: что убрать или на что заменить.',
  redo: '⚠️ Вариант почти как прошлый — нажми «🔄 Переписать» ещё раз.',
};

// r: строка вакансии + { ok, letter, problem, mode, instruction, same }. Письмо — в <pre>: копируется одним нажатием.
// После «📨 Отправил» (status = applied) подсказки заменяет строка «📨 Отклик отправлен …».
// Под письмом с правкой — куда записать факт о себе для всех писем (пожелание живёт только в письмах этой вакансии)
// Робот (этап 6): строку очереди и итога даёт robotLine из n8n/shared/robot.js (подключается перед этим файлом)
function letterText(r) {
  const head = `${LETTER_HEAD[r.mode] ?? LETTER_HEAD.new} · <a href="${r.url}">${esc(r.title)}</a> · ${esc(r.company)}`;
  if (!r.ok) {
    return [head, `⚠️ Письмо не получилось: ${esc(r.problem)}`, 'Нажми «🔄 Переписать», чтобы попробовать ещё раз.'].join('\n');
  }
  const sent = r.status === 'applied';
  const closed = r.status === 'archived';
  const robot = typeof robotLine === 'function' ? robotLine(r) : '';
  return [
    head,
    r.mode === 'revise' && r.instruction ? `<i>Пожелание: «${esc(r.instruction)}»</i>` : '',
    LETTER_SAME[r.same] ?? '',
    `<pre>${esc(r.letter)}</pre>`,
    // Робот включён, но вакансия ему не подходит (W5 «Format letter») — почему нет 🚀
    !sent && !closed && r.robot_hint ? `🤖 Робот не откликается: ${esc(r.robot_hint)}` : '',
    !sent && !closed && r.has_test && r.apply_result !== 'test' && !r.robot_hint ? '📝 У вакансии тест — ответы в форме отклика на hh.' : '',
    sent
      ? robot || `📨 Отклик отправлен${r.applied_at ? ` ${localDate(r.applied_at)}` : ''}`
      : closed
        ? '🔒 Вакансия закрыта на hh — отклик уже не отправить'
        : robot || '<i>Нажми на письмо — скопируется. Поправить — ответь на это сообщение.</i>',
    !sent && !closed && r.mode === 'revise' ? '<i>Факт о себе для всех писем — ⚙️ → 👤 Профиль → ➕ Дополнительно к резюме.</i>' : '',
  ]
    .filter(Boolean)
    .join('\n');
}

const job = $('Job').first().json;
const row = $('Gate').first().json.next;
const res = $input.first()?.json ?? {};
const code = Number(res.statusCode) || 0;
const body = res.body && typeof res.body === 'object' ? res.body : {};
const now = new Date().toISOString();
// Неудачи подряд до этой попытки («Claim» уже прибавил 1 в таблице — засчитываем её только при error)
const triesBefore = Number(row.apply_tries) || 0;

let group = body.group;
let outcome = body.outcome;
if (res.error || !code) [group, outcome] = ['retry', 'unreachable'];
else if (code === 409) [group, outcome] = ['retry', 'busy'];
else if (code === 423) [group, outcome] = ['block', body.blocked?.kind ?? 'blocked'];
else if (code === 429) [group, outcome] = ['block', 'cap'];
else if (code !== 200 || !group) [group, outcome] = ['error', 'error'];

const warnings = Array.isArray(body.warnings) ? body.warnings.filter(Boolean).join('; ') : '';
const update = { apply_state: '', apply_tries: triesBefore };
let layout = 'robot';
let card = null;
let shot = '';
let more = true;

if (group === 'retry' || group === 'block') {
  // Назад в очередь: робот занят, не отвечает или ждёт человека (тревогу пришлёт «Gate» следующего тика)
  Object.assign(update, { apply_state: 'queued' });
  layout = 'wait';
  more = group === 'block';
} else if (group === 'done') {
  Object.assign(update, {
    status: 'applied',
    apply_result: outcome,
    apply_by: outcome === 'already' ? 'hh' : 'robot',
    apply_letter: outcome === 'already' ? '' : (body.letter ?? ''),
    apply_note: warnings.slice(0, 300),
    applied_at: row.applied_at || now,
    apply_tries: 0,
  });
  layout = 'done';
} else if (group === 'manual') {
  Object.assign(update, {
    apply_result: outcome,
    apply_note: String(body.note ?? '').slice(0, 300),
    ...(outcome === 'test' && { has_test: true }),
    ...(outcome === 'external' && { apply_type: 'external' }),
  });
  layout = 'manual';
} else if (group === 'closed') {
  Object.assign(update, { status: 'archived', apply_result: outcome, apply_tries: 0 });
  layout = 'none';
} else if (group === 'dry') {
  Object.assign(update, { apply_result: 'dry_run', apply_note: String(body.note ?? '').slice(0, 300) });
  shot = body.shot ?? '';
} else {
  // error: попытка засчитана («Claim» прибавил 1); с 3-й — только вручную
  const tries = triesBefore + 1;
  Object.assign(update, {
    apply_result: 'error',
    apply_note: String(body.note ?? `ответ робота ${code}`).slice(0, 300),
    apply_tries: tries,
  });
  layout = tries >= 3 ? 'manual' : 'robot';
  shot = body.shot ?? '';
  more = false;
}

const next = { ...row, ...update };
// Строка для записи: только колонки таблицы (Save result пишет их поимённо)
const rowOut = {
  status: next.status,
  apply_state: next.apply_state ?? '',
  apply_result: next.apply_result ?? '',
  apply_letter: next.apply_letter ?? '',
  apply_note: next.apply_note ?? '',
  apply_by: next.apply_by ?? '',
  applied_at: next.applied_at ?? '',
  apply_tries: Math.max(0, Number(next.apply_tries) || 0),
  has_test: Boolean(next.has_test),
  apply_type: next.apply_type ?? 'hh',
};
if (group === 'done' || group === 'closed') card = { messageId: row.tg_message_id, text: cardText(next) };

return [
  {
    json: {
      id: row.id,
      chatId: job.chatId,
      messageId: row.tg_letter_id,
      layout,
      url: row.url,
      apply_url: row.apply_url,
      text: letterText({
        ...next,
        ok: Boolean(row.letter),
        mode: 'new',
        robot_wait: group === 'block' ? 'проверки — сейчас напишу, чего именно' : group === 'retry' ? 'своей очереди' : '',
      }),
      group,
      outcome,
      row: rowOut,
      card,
      shot,
      caption: shot ? `${group === 'dry' ? '🧪' : '⚠️'} ${esc(row.title)} · ${esc(String(body.note ?? outcome)).slice(0, 200)}` : '',
      sync: { action: 'panel', view: 'sync', id: row.id, chatId: job.chatId, tab: '', page: 1, queryId: '', messageId: 0, userMessageId: 0 },
      more,
    },
  },
];

// W9 · Sync job — перерисовать панель меню (W7), если на ней открыта эта вакансия (как W3 «Sync job»).
// Нода: Code, режим «Run Once for All Items». Вход: «Result» → sync.
return [{ json: $('Result').first().json.sync }];

// W9 · Next job — продолжить очередь: задание для самого W9 (вызов без ожидания — новый запуск, чистое состояние).
// Нода: Code, режим «Run Once for All Items».
return [{ json: { op: 'tick', fromUser: false } }];

// W9 · Resume plan — ▶️ или /go после блока: робот перепроверил вход и капчу (POST /resume).
// Нода: Code, режим «Run Once for All Items». Вход: ответ робота (полный: statusCode, body { ok, loggedIn, blocked })
// или { error }; «Job» — queryId (▶️ — ответить всплывашкой) или его нет (/go — ответить сообщением).
// Выход: { ok, toast, reply } — дальше в любом случае тик очереди: «Gate» поправит тревогу, если блок снят

const job = $('Job').first().json;
const res = $input.first()?.json ?? {};
const body = res.body && typeof res.body === 'object' ? res.body : {};
const WAIT = { login: 'робот всё ещё не вошёл в hh', captcha: 'капча ещё на экране', smart: 'капча ещё на экране', limit: 'лимит hh ещё не прошёл' };
let toast;
if (res.error || Number(res.statusCode) !== 200) toast = '⚠️ Робот не отвечает — scripts/deploy.sh --applier';
else if (body.blocked) toast = `⏸ Пока нет: ${WAIT[body.blocked.kind] ?? body.blocked.kind}`;
else toast = '▶️ Робот снова в работе';
return [{ json: { ok: !body.blocked && !res.error, toast, reply: job.queryId ? '' : toast } }];

// W9 · Captcha plan — ответ пользователя на фото капчи ушёл роботу (POST /captcha): что дальше.
// Нода: Code, режим «Run Once for All Items». Вход: ответ робота (полный: statusCode, body { ok, kind, shot }) или
// { error }; «Job» — promptId (фото капчи), userMessageId (ответ пользователя).
// Выход: { solved, deleteIds, notice, text }
//   solved — капча принята или уже не нужна (409: блок сняли раньше — /go, «Общий экран»): фото и ответ удалить,
//   сообщение (с кнопками меню — ForceReply их спрятал), дальше очередь; не подошла — новое фото капчи (notice → те же
//   ноды, что у «Gate»).

// Время человека (13.10.2026, docs/onboarding.md): часовой пояс — настройка profile.tz (IANA, например Asia/Bangkok),
// иначе пояс компьютера (USER_TZ из .env — его пишет мастер установки), иначе Москва. Расписание сбора по-прежнему
// считается по Москве (n8n/shared/schedule.js): hh публикует вакансии по МСК.
// Общий код: строка «// @include n8n/shared/time.js» — раньше n8n/shared/card.js и n8n/shared/robot.js (им нужен TZ).
// Пояс берётся из ноды «Settings», если она есть в workflow и уже выполнилась; без неё — USER_TZ.

const MSK_TZ = 'Europe/Moscow';
const validTz = (tz) => {
  try {
    return Boolean(tz) && Boolean(new Intl.DateTimeFormat('en-GB', { timeZone: tz }));
  } catch {
    return false;
  }
};

// Пояс этого запуска
function currentTz() {
  let tz = '';
  try {
    const row = $('Settings')
      .all()
      .map((i) => i.json)
      .find((r) => r?.name === 'profile.tz');
    tz = row ? JSON.parse(row.value_json) : '';
  } catch {
    // в workflow нет ноды «Settings» или строка битая — пояс компьютера
  }
  const env = typeof $env === 'undefined' ? '' : $env.USER_TZ;
  return [tz, env, MSK_TZ].find(validTz);
}
const TZ = currentTz();

// Части даты в поясе tz числами: { y, mo, d, h, mi }
function zonedParts(ms, tz = TZ) {
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  }).formatToParts(new Date(ms));
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  return { y: get('year'), mo: get('month'), d: get('day'), h: get('hour'), mi: get('minute') };
}
const pad2 = (n) => String(n).padStart(2, '0');

// 1760340720000 → '14:32'
const localHM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.h)}:${pad2(p.mi)}`;
};
// → '07.10'
const localDM = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${pad2(p.d)}.${pad2(p.mo)}`;
};
// → '2026-10-07' — ключ дня
const localDay = (ms, tz = TZ) => {
  const p = zonedParts(ms, tz);
  return `${p.y}-${pad2(p.mo)}-${pad2(p.d)}`;
};
const localHour = (ms, tz = TZ) => zonedParts(ms, tz).h;

// Смещение пояса от UTC в минутах в момент ms (Бангкок: +420)
function tzOffsetMin(ms, tz = TZ) {
  const p = zonedParts(ms, tz);
  return Math.round((Date.UTC(p.y, p.mo - 1, p.d, p.h, p.mi) - Math.floor(ms / 60000) * 60000) / 60000);
}

// 'UTC+7', 'UTC+5:30', 'UTC−4'
function tzLabel(tz = TZ, ms = Date.now()) {
  const off = tzOffsetMin(ms, tz);
  const abs = Math.abs(off);
  return `UTC${off < 0 ? '−' : '+'}${Math.floor(abs / 60)}${abs % 60 ? `:${pad2(abs % 60)}` : ''}`;
}

// Начало «дня», который начинается в hour:00 по местному: последний такой момент не позже ms
function localDayStart(ms, tz = TZ, hour = 0) {
  const p = zonedParts(ms, tz);
  let start = Date.UTC(p.y, p.mo - 1, p.d, hour) - tzOffsetMin(ms, tz) * 60000;
  if (start > ms) start -= 24 * 3600 * 1000;
  return start;
}

// Тихие часы 23:00–09:00 по местному: карточки и сводка — без звука, тревоги — со звуком
const quietHours = (ms = Date.now(), tz = TZ) => {
  const h = localHour(ms, tz);
  return h >= 23 || h < 9;
};

// Время по местному и в скобках по Москве: '14:32 (10:32 МСК)'; пояс совпадает с Москвой — '10:32 МСК'
const localMsk = (ms, tz = TZ) =>
  tzOffsetMin(ms, tz) === tzOffsetMin(ms, MSK_TZ) ? `${localHM(ms, MSK_TZ)} МСК` : `${localHM(ms, tz)} (${localHM(ms, MSK_TZ)} МСК)`;

// Момент ISO (applied_at) → дата и время по местному: '2026-10-06T21:17:55Z' → '07.10', '04:17'
const localDate = (iso) => (Date.parse(iso) ? localDM(Date.parse(iso)) : '');
const localTime = (iso) => (Date.parse(iso) ? localHM(Date.parse(iso)) : '');

// Общий код карточки вакансии в Telegram: W2 «Format card» и W3 «Apply choice».
// В Code-ноду попадает при сборке: строка «// @include n8n/shared/card.js» заменяется этим файлом
// (scripts/build-workflows.mjs, scripts/run-code-node.mjs). Раньше него — n8n/shared/time.js (localDate).

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const EXPERIENCE = { noExperience: 'без опыта', between1And3: '1–3 г.', between3And6: '3–6 л.', moreThan6: '6+ л.' };
const CURRENCY = { RUR: '₽', USD: '$', EUR: '€', KZT: '₸', BYR: 'Br', UZS: 'сум' };

// Решение нейросети (колонка decision)
const VERDICT = { apply: '🟢 apply', maybe: '🟡 maybe', skip: '🔴 skip', error: '⚠️ не оценено' };
// Кнопки пользователя: callback_data = v:<id строки>:<choice>, решение — в колонку my_decision.
// earlier — «📨 Уже откликался» (до бота, 07.10.2026): status = applied без письма и без applied_at,
// без «Почему?» и вне теневого режима (сравниваются только apply / maybe / skip)
const CHOICE = { apply: '✅ Откликнусь', maybe: '🤔 Возможно', skip: '❌ Мимо', earlier: '📨 Откликался раньше' };
// «🚫 В ЧС» на карточке (07.10.2026): компания уходит в чёрный список, вакансия — ❌ с этой причиной
const BAN_REASON = 'чёрный список';
const STATUS_BY_CHOICE = { apply: 'approved', maybe: 'maybe', skip: 'skipped', earlier: 'applied' };

const short = (n) => (n >= 1000 ? `${Math.round(n / 1000)}k` : String(n));

function salary(r) {
  if (!r.salary_from && !r.salary_to) return '';
  const range =
    r.salary_from && r.salary_to
      ? `${short(r.salary_from)}–${short(r.salary_to)}`
      : r.salary_from
        ? `от ${short(r.salary_from)}`
        : `до ${short(r.salary_to)}`;
  return `💰 ${range} ${CURRENCY[r.currency] ?? r.currency ?? ''}${r.salary_gross ? ' до налогов' : ''}`;
}

// «Москва, Сербия, Грузия, Армения» → «Москва, Сербия +2»
function areas(s) {
  const list = String(s ?? '').split(', ').filter(Boolean);
  return list.length > 2 ? `${list.slice(0, 2).join(', ')} +${list.length - 2}` : list.join(', ');
}

